local L = select(2, ...).L

L["binding.birch.description"] = "Pale and papery, with dark flecks. Likely the only book here that would float."
L["binding.birch.name"] = "Birch Bark"
L["binding.bone.description"] = "Rawhide stretched taut over a frame and shut with two carved bone toggles. Creaks in the cold."
L["binding.bone.name"] = "Bone & Rawhide"
L["binding.brasscase.description"] = "A brass case engraved with a leaping fish over the reeds, with a latch that clicks like it means it."
L["binding.brasscase.name"] = "Brass Hunter's Case"
L["binding.buckram.description"] = "Stiff sea-green cloth with cream rules. Spray beads up and rolls straight off."
L["binding.buckram.name"] = "Sea-Green Buckram"
L["binding.canvas.description"] = "Plain khaki canvas, stencilled with a number nobody remembers assigning. Fits a coat pocket, just."
L["binding.canvas.name"] = "Canvas Field Pad"
L["binding.chartlinen.description"] = "Pale linen printed with an old chart, its depth lines worn soft at the corners by a few seasons of thumbs."
L["binding.chartlinen.name"] = "Tide-Chart Linen"
L["binding.copper.description"] = "Copper plates riveted over boards, gone green at the seams. Loud to close, impossible to dent."
L["binding.copper.name"] = "Riveted Copper"
L["binding.coral.description"] = "Branches of red coral set into sea-green leather, with pearls where the branches end."
L["binding.coral.name"] = "Coral Inlay"
L["binding.driftwood.description"] = "Three boards of grey driftwood, nailed to a leather spine. Heavy, honest and faintly salty."
L["binding.driftwood.name"] = "Driftwood Boards"
L["binding.eelskin.description"] = "Strips of eelskin sewn side by side, dark and slick, with a shine that moves when the light does."
L["binding.eelskin.name"] = "Eelskin"
L["binding.field.description"] = "Plain brown leather, made to be rained on, and it usually is."
L["binding.field.name"] = "Field Leather"
L["binding.frosthide.description"] = "Hide cured in the cold until it went white, trimmed with fur along the spine for gloveless hands."
L["binding.frosthide.name"] = "Frost-Tanned Hide"
L["binding.kodo.description"] = "A thick plains hide with the hair worn off in patches, laced shut with rawhide. It will outlast the angler."
L["binding.kodo.name"] = "Kodo Hide"
L["binding.kraft.description"] = "Brown paper rubbed with beeswax until it shrugs off rain. Tied with twine, because buttons fall off."
L["binding.kraft.name"] = "Waxed Kraft"
L["binding.lacquer.description"] = "Layer upon layer of red lacquer, polished until it holds a reflection, with a gilt carp swimming in it."
L["binding.lacquer.name"] = "Lacquered Red"
L["binding.maplinen.description"] = "A hand-drawn map on linen, the trail dotted in red and an X where somebody swears the big one lives."
L["binding.maplinen.name"] = "Map Linen"
L["binding.morocco.description"] = "Red goatskin tooled all over in gold lattice, the kind of binding usually kept behind glass."
L["binding.morocco.name"] = "Gilded Morocco"
L["binding.moss.description"] = "Leather left too long on a damp bank. The moss took hold, and the book seems happier for it."
L["binding.moss.name"] = "Mossbound"
L["binding.netcork.description"] = "Cork boards under a knotted net, with a float tied on. It will not sink, which is more than most books can say."
L["binding.netcork.name"] = "Net over Cork"
L["binding.oilskin.description"] = "Waxed yellow cloth that sheds rain and spray. You can find it at the bottom of the boat, which is the point."
L["binding.oilskin.name"] = "Oilskin Yellow"
L["binding.pearl.description"] = "A cover of shell, cut piece by piece and fitted like tiles. It shifts colour every time the book is turned."
L["binding.pearl.name"] = "Mother-of-Pearl"
L["binding.planks.description"] = "Thin planks strapped together with leather and brass buckles. Doubles as a cutting board in a pinch."
L["binding.planks.name"] = "Bound Planks"
L["binding.sailcloth.description"] = "Old sail, tarred black against the weather and whipped round the edges with twine."
L["binding.sailcloth.name"] = "Tarred Sailcloth"
L["binding.scrimshaw.description"] = "An old ivory panel scratched with a ship and a fish by some sailor with a long voyage and a sharp knife."
L["binding.scrimshaw.name"] = "Scrimshaw Panel"
L["binding.shagreen.description"] = "Ray skin, pebbled like frost, with the pale star at its centre the old makers always kept."
L["binding.shagreen.name"] = "Stingray Shagreen"
L["binding.shagreenbone.description"] = "Green ray-skin, every pebble of it, with bone laid in like a sunrise. Made for a captain who liked his books to match the saloon."
L["binding.shagreenbone.name"] = "Shagreen and Bone"
L["binding.sharkskin.description"] = "Rough grey hide with silver tooling. It won't slip out of a wet hand."
L["binding.sharkskin.name"] = "Sharkskin"
L["binding.snakeskin.description"] = "A long swamp snake’s skin, still patterned with the diamonds it hunted by. Cool to the touch, always."
L["binding.snakeskin.name"] = "Snakeskin"
L["binding.tartan.description"] = "Thick green-and-navy wool with a red line through it. Warm hands, damp pages, no regrets."
L["binding.tartan.name"] = "Tartan Wool"
L["binding.tooled.description"] = "Dark leather tooled with reeds and leaping fish, by someone with a sharp knife and a long winter."
L["binding.tooled.name"] = "Tooled Leather"
L["binding.trophycase.description"] = "A dark wood case with a glass front, and behind the glass a fish cast in gold. Opens like a cabinet."
L["binding.trophycase.name"] = "Gilded Trophy Case"
L["binding.turtle.description"] = "Polished shell plates, amber and smoke, set into a dark frame. Older than the book, and likely to outlive it."
L["binding.turtle.name"] = "Turtle Shell"
L["binding.velvet.description"] = "Midnight velvet embroidered with silver stars and a moon. Best read by lantern, which is when it gets read."
L["binding.velvet.name"] = "Night Velvet"
L["binding.verdigris.description"] = "Copper corners and a copper clasp, gone green in the sea air. It was bright once, briefly."
L["binding.verdigris.name"] = "Verdigris"
L["good.core.crest.fish.12238.description"] = "A broad grey grouper on the grey sea it is named for, mouth open as ever."
L["good.core.crest.fish.12238.name"] = "{fish} Crest"
L["good.core.crest.fish.13422.description"] = "A stone-scaled eel coiled across blue water. Armourers covet the shield."
L["good.core.crest.fish.13422.name"] = "{fish} Crest"
L["good.core.crest.fish.13754.description"] = "A heavy blue fish on the open sea, built like a fist."
L["good.core.crest.fish.13754.name"] = "{fish} Crest"
L["good.core.crest.fish.13755.description"] = "A pale squid on winter ice-blue, every arm untangled at last."
L["good.core.crest.fish.13755.name"] = "{fish} Crest"
L["good.core.crest.fish.13756.description"] = "A bass on lake green, mouth wide enough for the whole season."
L["good.core.crest.fish.13756.name"] = "{fish} Crest"
L["good.core.crest.fish.13757.description"] = "An eel across a stormy field, sparks still at its edges."
L["good.core.crest.fish.13757.name"] = "{fish} Crest"
L["good.core.crest.fish.13758.description"] = "A barred perch on a field of ember red. The gills are the brightest thing on it."
L["good.core.crest.fish.13758.name"] = "{fish} Crest"
L["good.core.crest.fish.13759.description"] = "A violet snapper on night water. Earned in the dark, mostly."
L["good.core.crest.fish.13759.name"] = "{fish} Crest"
L["good.core.crest.fish.13760.description"] = "A gold-flecked salmon rising through green water, catching every hour of light."
L["good.core.crest.fish.13760.name"] = "{fish} Crest"
L["good.core.crest.fish.13888.description"] = "A lobster on the blue, claws first, as it insists."
L["good.core.crest.fish.13888.name"] = "{fish} Crest"
L["good.core.crest.fish.13889.description"] = "A frost-pale salmon on cold blue. Every colour of it, caught before it melted."
L["good.core.crest.fish.13889.name"] = "{fish} Crest"
L["good.core.crest.fish.13890.description"] = "A fish in bony plates on ice-blue, its armour finally outmatched."
L["good.core.crest.fish.13890.name"] = "{fish} Crest"
L["good.core.crest.fish.13893.description"] = "The big cousin on a field of deep sea. Took both hands, and a friend, many times."
L["good.core.crest.fish.13893.name"] = "{fish} Crest"
L["good.core.crest.fish.1467.description"] = "A sunfish on a field of lake green. For the angler who has seen every spot it can wear."
L["good.core.crest.fish.1467.name"] = "{fish} Crest"
L["good.core.crest.fish.16967.description"] = "A yellowfin tuna on river green, long fins swept back like banners."
L["good.core.crest.fish.16967.name"] = "{fish} Crest"
L["good.core.crest.fish.16968.description"] = "A barred hunter crossing blue water, teeth first."
L["good.core.crest.fish.16968.name"] = "{fish} Crest"
L["good.core.crest.fish.16969.description"] = "A sailfish on the jungle coast's green-blue, sail raised for the audience."
L["good.core.crest.fish.16969.name"] = "{fish} Crest"
L["good.core.crest.fish.16970.description"] = "A green and gold mahi on the jungle coast, bright as the day it was landed."
L["good.core.crest.fish.16970.name"] = "{fish} Crest"
L["good.core.crest.fish.19807.description"] = "A freckled fish on the contest coast. Every kind of it, every contest."
L["good.core.crest.fish.19807.name"] = "{fish} Crest"
L["good.core.crest.fish.19975.description"] = "A squat brown fish on murky water. The shield, mercifully, does not smell."
L["good.core.crest.fish.19975.name"] = "{fish} Crest"
L["good.core.crest.fish.21071.description"] = "A small fish with its tall fin raised, on hillside-stream green."
L["good.core.crest.fish.21071.name"] = "{fish} Crest"
L["good.core.crest.fish.21153.description"] = "The elder of its kind, grown old and grand, its fin a banner on green water."
L["good.core.crest.fish.21153.name"] = "{fish} Crest"
L["good.core.crest.fish.251524.description"] = "A gold fish trailing blue silk on green water. Still nobody knows how it got here."
L["good.core.crest.fish.251524.name"] = "{fish} Crest"
L["good.core.crest.fish.4603.description"] = "A yellowtail rising through blue water, tail first in every sense."
L["good.core.crest.fish.4603.name"] = "{fish} Crest"
L["good.core.crest.fish.6289.description"] = "A snapper all jaw, on pond green. Earned one bite at a time."
L["good.core.crest.fish.6289.name"] = "{fish} Crest"
L["good.core.crest.fish.6291.description"] = "The smallest fish on any shield, and the hardest to stop catching."
L["good.core.crest.fish.6291.name"] = "{fish} Crest"
L["good.core.crest.fish.6299.description"] = "A sad grey fish on dark water. Somebody had to collect them all. It was you."
L["good.core.crest.fish.6299.name"] = "{fish} Crest"
L["good.core.crest.fish.6303.description"] = "A barred mackerel on open sea, slipping out of the frame as usual."
L["good.core.crest.fish.6303.name"] = "{fish} Crest"
L["good.core.crest.fish.6308.description"] = "Whiskers, grudge and river green. Every last one of them has sulked on your line."
L["good.core.crest.fish.6308.name"] = "{fish} Crest"
L["good.core.crest.fish.6317.description"] = "Teeth on a field of loch water. Dwarves would approve, then count their fingers."
L["good.core.crest.fish.6317.name"] = "{fish} Crest"
L["good.core.crest.fish.6358.description"] = "An oily salmon on blue, gleaming. Every colour the oil could make, accounted for."
L["good.core.crest.fish.6358.name"] = "{fish} Crest"
L["good.core.crest.fish.6359.description"] = "A red snapper rising through warm water, for the angler who has seen it in every colour it comes in."
L["good.core.crest.fish.6359.name"] = "{fish} Crest"
L["good.core.crest.fish.6361.description"] = "An albacore with its rainbow fins spread wide, colours that never fade on a shield."
L["good.core.crest.fish.6361.name"] = "{fish} Crest"
L["good.core.crest.fish.6362.description"] = "A mottled cod on deep blue, stubborn as the rocks it hides among."
L["good.core.crest.fish.6362.name"] = "{fish} Crest"
L["good.core.crest.fish.6458.description"] = "A small fish on murky water, as clean as it will ever be."
L["good.core.crest.fish.6458.name"] = "{fish} Crest"
L["good.core.crest.fish.6522.description"] = "Something with too many eyes on a field of bad water. Proof of a strong stomach."
L["good.core.crest.fish.6522.name"] = "{fish} Crest"
L["good.core.crest.fish.8365.description"] = "A trout with a shining head, on river green. The smith has stopped asking."
L["good.core.crest.fish.8365.name"] = "{fish} Crest"
L["good.core.crest.plain.description"] = "No emblem, only the owner's name. Plenty of fine anglers never wanted more."
L["good.core.crest.plain.name"] = "Plain"
L["good.core.soundset.driftwood.description"] = "Soft wooden knocks, like a hull bumping the jetty."
L["good.core.soundset.driftwood.name"] = "Driftwood"
L["good.core.soundset.dulcimer.description"] = "A hammered dulcimer from the corner of a dockside tavern, struck quick and bright."
L["good.core.soundset.dulcimer.name"] = "Tavern Dulcimer"
L["good.core.soundset.frost.description"] = "Icicles chiming against one another in a cold wind, ringing long after they stop moving."
L["good.core.soundset.frost.name"] = "Frost Chimes"
L["good.core.soundset.gilded.description"] = "Small, bright bells. A touch grand for a mackerel, and none the worse for it."
L["good.core.soundset.gilded.name"] = "Gilded"
L["good.core.soundset.gizmo.description"] = "Clockwork ticking, a spring letting go and two cheerful bleeps. It almost certainly works."
L["good.core.soundset.gizmo.name"] = "Gnomish Gizmo"
L["good.core.soundset.glass.description"] = "Green glass floats knocking together on a net, with bubbles rising past them."
L["good.core.soundset.glass.name"] = "Glass Floats"
L["good.core.soundset.harp.description"] = "A harp in a forest glade, a short sweep of strings and the leaves answering."
L["good.core.soundset.harp.name"] = "Harp of the Glade"
L["good.core.soundset.kalimba.description"] = "A thumb piano by running water, two notes and a little buzz, as if the creek plucked them."
L["good.core.soundset.kalimba.name"] = "Kalimba Creek"
L["good.core.soundset.marimba.description"] = "Warm wooden bars, rolled quickly up the scale like a wave coming in."
L["good.core.soundset.marimba.name"] = "Marimba Shore"
L["good.core.soundset.musicbox.description"] = "A tiny wind-up tune from a box with a fish painted on the lid. Two turns of the key, no more."
L["good.core.soundset.musicbox.name"] = "Music Box"
L["good.core.soundset.rain.description"] = "Drops landing on still water, one after another, and the faint hush of rain behind them."
L["good.core.soundset.rain.name"] = "Rain on the Lake"
L["good.core.soundset.shipbell.description"] = "The brass bell on the mast, rung for the catch, with the rope and timbers creaking under it."
L["good.core.soundset.shipbell.name"] = "Ship's Bell"
L["good.core.soundset.steelpan.description"] = "Bright steel drums from a warm lagoon, two notes that sound like the tide is on your side."
L["good.core.soundset.steelpan.name"] = "Steel Pan Lagoon"
L["good.core.soundset.wardrums.description"] = "Deep drums and a low horn from the hills: a catch announced like the start of a march."
L["good.core.soundset.wardrums.name"] = "War Drums"
L["good.core.toaststyle.birch.description"] = "Written on a strip of peeled bark and tied with twine. The ink sinks in and stays."
L["good.core.toaststyle.birch.name"] = "Birch Scroll"
L["good.core.toaststyle.bottle.description"] = "Rolled up, corked and given to the tide. It washed back with a better catch than it left with."
L["good.core.toaststyle.bottle.name"] = "Driftglass Bottle"
L["good.core.toaststyle.chart.description"] = "Torn from a chart nobody should have sold. Soundings, rhumb lines and a compass rose that still points north."
L["good.core.toaststyle.chart.name"] = "Sea Chart"
L["good.core.toaststyle.foil.description"] = "The rare one, pulled from the pack on the first try. Hold it to the light and the whole lake runs through it."
L["good.core.toaststyle.foil.name"] = "Prize Foil"
L["good.core.toaststyle.folio.description"] = "Gold leaf, lapis and vermilion, laid on vellum by a scribe with too much time and not enough fish."
L["good.core.toaststyle.folio.name"] = "Illuminated Folio"
L["good.core.toaststyle.frost.description"] = "Left out overnight on the ice. The rime grew in from the corners while the ink was still wet."
L["good.core.toaststyle.frost.name"] = "Frostbitten"
L["good.core.toaststyle.goblin.description"] = "Printed on a ticker that never stops. The rivets are load-bearing. Nobody knows what the gear does."
L["good.core.toaststyle.goblin.name"] = "Goblin Ticker"
L["good.core.toaststyle.kelp.description"] = "A spine wrapped in kelp and studded with pearls, the page shining like the inside of a shell."
L["good.core.toaststyle.kelp.name"] = "Kelp & Pearl"
L["good.core.toaststyle.lanternglow.description"] = "A warm lamp glowing behind each catch, for anglers who stay out past dark."
L["good.core.toaststyle.lanternglow.name"] = "Lantern Glow"
L["good.core.toaststyle.leaf.description"] = "One great leaf, pressed flat between two heavy books and dried gold. The veins do the ruling."
L["good.core.toaststyle.leaf.name"] = "Pressed Leaf"
L["good.core.toaststyle.moon.description"] = "Night-blue vellum written in silver, for the catches that come in after the lanterns."
L["good.core.toaststyle.moon.name"] = "Moonlit Vellum"
L["good.core.toaststyle.page.description"] = "A fresh page torn from the logbook and pinned to a leather spine. Brass trim, red ink."
L["good.core.toaststyle.page.name"] = "Torn Page"
L["good.core.toaststyle.ripple.description"] = "Blue leather and silver trim, with faint rings spreading across the page as if something just bit."
L["good.core.toaststyle.ripple.name"] = "Ripple"
L["good.core.toaststyle.rune.description"] = "Not paper at all: a bronze plate, the catch hammered in and the runes cut round it to keep it honest."
L["good.core.toaststyle.rune.name"] = "Rune-Plate"
L["good.core.toaststyle.ship.description"] = "A page from the ship’s log, lashed to a sailcloth spine. Tide columns ruled in navy, an anchor in the margin."
L["good.core.toaststyle.ship.name"] = "Ship's Log"
L["good.core.toaststyle.sonar.description"] = "Built by an engineer who wanted to see the fish before they saw him. It hums, it pings, and it has never once been wrong about a ping."
L["good.core.toaststyle.sonar.name"] = "Sonar Scope"
L["good.core.toaststyle.storm.description"] = "The catch you made when everyone sensible had gone in. The pennant says gale; the angler says one more cast."
L["good.core.toaststyle.storm.name"] = "Storm Front"
L["good.core.toaststyle.tidepool.description"] = "A page that went in the water and came back out. Sand in the fold, a shell left behind."
L["good.core.toaststyle.tidepool.name"] = "Tidepool"
L["variety.12238.barred.description"] = "Broad dark bars that fade when it rests. It rests a lot."
L["variety.12238.barred.name"] = "Barred"
L["variety.12238.bigmouth.description"] = "A mouth that could swallow a lantern. Possibly did."
L["variety.12238.bigmouth.name"] = "Bigmouth"
L["variety.12238.brown.description"] = "Brown from muddy estuaries. Makes the same stew."
L["variety.12238.brown.name"] = "Brown"
L["variety.12238.coast-grey.description"] = "Grey mottled with darker grey, broad as a shield. Moves only when it must."
L["variety.12238.coast-grey.name"] = "Coast Grey"
L["variety.12238.moon-pale.description"] = "Pale grey, as if the moon bleached it. A better stew than first impression."
L["variety.12238.moon-pale.name"] = "Moon-pale"
L["variety.12238.moonkissed.description"] = "Pale specks shine on it like stars on dark water. Caught under a full moon, if the stories are right."
L["variety.12238.moonkissed.name"] = "Moonkissed"
L["variety.12238.mottled.description"] = "Dark blotches like rocks under shallow water. Sits still and waits."
L["variety.12238.mottled.name"] = "Mottled"
L["variety.12238.night-dark.description"] = "Nearly black, from the deepest part of the bay. Nobody sees it until it bites."
L["variety.12238.night-dark.name"] = "Night-dark"
L["variety.12238.rust-spotted.description"] = "Rusty spots over grey, like an anchor left out too long."
L["variety.12238.rust-spotted.name"] = "Rust-spotted"
L["variety.12238.silverscale.description"] = "Silver where it should be grey. Coast anglers say it's lucky. Coast anglers need luck."
L["variety.12238.silverscale.name"] = "Silverscale"
L["variety.13422.banded.description"] = "Rings of dark stone down its length, like a carved pillar."
L["variety.13422.banded.name"] = "Banded"
L["variety.13422.bedrock-ancient.description"] = "Huge stone scales, cracked and glowing amber in the seams. As old as the cliff it came from, by the look."
L["variety.13422.bedrock-ancient.name"] = "Bedrock Ancient"
L["variety.13422.gold-veined.description"] = "Gold runs through the grey like ore in rock. Jewellers have been known to weep."
L["variety.13422.gold-veined.name"] = "Gold-veined"
L["variety.13422.greenstone.description"] = "Mossy green scales. Looks like it lay on a riverbed for a century."
L["variety.13422.greenstone.name"] = "Greenstone"
L["variety.13422.marble.description"] = "White veined with grey, like a temple floor. Armourers fight over it."
L["variety.13422.marble.name"] = "Marble"
L["variety.13422.moray-spotted.description"] = "Dark spots all over, like a moray's hide. Equally pleased to see you."
L["variety.13422.moray-spotted.name"] = "Moray-spotted"
L["variety.13422.obsidian.description"] = "Black glassy scales with an edge on every one. Handle by the tail, and carefully."
L["variety.13422.obsidian.name"] = "Obsidian"
L["variety.13422.pebble-scaled.description"] = "Scales like small grey stones. Armourers pay well. The eel disagrees."
L["variety.13422.pebble-scaled.name"] = "Pebble-scaled"
L["variety.13422.sandstone.description"] = "Warm sandy scales, from desert coasts. Still bites."
L["variety.13422.sandstone.name"] = "Sandstone"
L["variety.13422.slate.description"] = "Blue-grey, like roofing slate. Just as hard to cut."
L["variety.13422.slate.name"] = "Slate"
L["variety.13754.barred.description"] = "Broad bars across the gloss, like a fish dressed for battle."
L["variety.13754.barred.name"] = "Barred"
L["variety.13754.bronzeback.description"] = "A bronze back and a pale belly. Heavy enough to anchor a skiff."
L["variety.13754.bronzeback.name"] = "Bronzeback"
L["variety.13754.cobalt.description"] = "Deep cobalt blue that shimmers violet. Looks like a jewel. Weighs like an anvil."
L["variety.13754.cobalt.name"] = "Cobalt"
L["variety.13754.dappled.description"] = "Light dapples across its back like sun through shallow water."
L["variety.13754.dappled.name"] = "Dappled"
L["variety.13754.green-glass.description"] = "Green as a bottle held to the light. Just as heavy."
L["variety.13754.green-glass.name"] = "Green Glass"
L["variety.13754.humpbacked.description"] = "A hump of muscle behind the head. Pulls like a mule."
L["variety.13754.humpbacked.name"] = "Humpbacked"
L["variety.13754.mirror.description"] = "So glossy the angler can check their hair in it. Most don't, after the fight."
L["variety.13754.mirror.name"] = "Mirror"
L["variety.13754.onyx.description"] = "Black gloss, as if lacquered. Swallows the light, and the hook."
L["variety.13754.onyx.name"] = "Onyx"
L["variety.13754.polished.description"] = "Stout, blue and polished like a new boot. Pulls like something twice its size."
L["variety.13754.polished.name"] = "Polished"
L["variety.13754.tidemight.description"] = "Lines of sea-light run under the gloss. It pulls like the tide itself is on the other end."
L["variety.13754.tidemight.name"] = "Tidemight"
L["variety.13755.blueflash.description"] = "Flashes blue when touched. It is not pleased to be touched."
L["variety.13755.blueflash.name"] = "Blueflash"
L["variety.13755.blushing.description"] = "Flushed red all over, the way squid go when startled. Usually by the angler."
L["variety.13755.blushing.name"] = "Blushing"
L["variety.13755.brindled.description"] = "Dark stripes along the mantle, like frost cracks in a window."
L["variety.13755.brindled.name"] = "Brindled"
L["variety.13755.crimson.description"] = "Deep crimson all over, the colour of a warning. Inks twice as much."
L["variety.13755.crimson.name"] = "Crimson"
L["variety.13755.frost-pink.description"] = "Pale pink, freckled with dark spots that come and go as it breathes. Arrives with the frost."
L["variety.13755.frost-pink.name"] = "Frost-pink"
L["variety.13755.frostlight.description"] = "Glows pale blue in the dark, like moonlight on new snow. Only seen in the deepest cold."
L["variety.13755.frostlight.name"] = "Frostlight"
L["variety.13755.glassfrost.description"] = "Clear as ice, rimed at the edges. Melts a little in the hand, or seems to."
L["variety.13755.glassfrost.name"] = "Glassfrost"
L["variety.13755.long-armed.description"] = "Arms twice the usual length. More to untangle, which seemed impossible."
L["variety.13755.long-armed.name"] = "Long-armed"
L["variety.13755.milky.description"] = "White and nearly see-through. Easy to lose in the ice."
L["variety.13755.milky.name"] = "Milky"
L["variety.13755.ring-spotted.description"] = "Dark rings across the mantle like a row of watching eyes."
L["variety.13755.ring-spotted.name"] = "Ring-spotted"
L["variety.13756.bronze.description"] = "Bronze with faint bars, from rocky water. Jumps more than the green ones."
L["variety.13756.bronze.name"] = "Bronze"
L["variety.13756.bucketmouth.description"] = "A mouth like a bucket. Swallows lures whole, and sometimes small ducks."
L["variety.13756.bucketmouth.name"] = "Bucketmouth"
L["variety.13756.golden.description"] = "Gold with a bronze stripe. A summer's afternoon of a fish."
L["variety.13756.golden.name"] = "Golden"
L["variety.13756.lateral-lined.description"] = "Green with a dark line down each flank. Lurks under anything that gives shade."
L["variety.13756.lateral-lined.name"] = "Lateral-lined"
L["variety.13756.lily-pad.description"] = "Mottled like a pond full of lily pads, which is exactly where it lurks."
L["variety.13756.lily-pad.name"] = "Lily-pad"
L["variety.13756.midsummer.description"] = "Glows warm gold, like the longest evening of the year. Caught at the height of summer, and only then."
L["variety.13756.midsummer.name"] = "Midsummer"
L["variety.13756.red-eyed.description"] = "Eyes red as a summer sunset. Feeds hardest in the evening heat."
L["variety.13756.red-eyed.name"] = "Red-eyed"
L["variety.13756.shadow.description"] = "Black-green and hard to see. Lives in the shade and prefers it."
L["variety.13756.shadow.name"] = "Shadow"
L["variety.13756.sun-bleached.description"] = "Pale from shallow summer water, the stripe faded to a smudge. Warm to hold."
L["variety.13756.sun-bleached.name"] = "Sun-bleached"
L["variety.13756.tiger.description"] = "Dark bars broken like tiger stripes. Fights like one, briefly."
L["variety.13756.tiger.name"] = "Tiger"
L["variety.13757.blackout.description"] = "Black and silent until touched. Then not silent at all."
L["variety.13757.blackout.name"] = "Blackout"
L["variety.13757.bolt-striped.description"] = "Yellow zigzags down the flanks, like a child's drawing of lightning."
L["variety.13757.bolt-striped.name"] = "Bolt-striped"
L["variety.13757.ember-bellied.description"] = "An orange belly, like an electric eel of warm rivers. Bites with a spark."
L["variety.13757.ember-bellied.name"] = "Ember-bellied"
L["variety.13757.long.description"] = "A fin that runs the whole length of its body. It ripples like a flag in a gale."
L["variety.13757.long.name"] = "Long"
L["variety.13757.ozone.description"] = "Smells of rain after a storm. The air around it goes sharp."
L["variety.13757.ozone.name"] = "Ozone"
L["variety.13757.slate.description"] = "Grey as storm clouds. Hums at a lower note."
L["variety.13757.slate.name"] = "Slate"
L["variety.13757.spark-spotted.description"] = "Pale spots that crackle when it thrashes. Gloves are no help."
L["variety.13757.spark-spotted.name"] = "Spark-spotted"
L["variety.13757.stormcaller.description"] = "Blue lightning forks across its body and into the water. Clouds gather while it's on the line, or seem to."
L["variety.13757.stormcaller.name"] = "Stormcaller"
L["variety.13757.thunder-dark.description"] = "Olive-dark and buzzing. Tingles. Don't lick it."
L["variety.13757.thunder-dark.name"] = "Thunder-dark"
L["variety.13757.white-bolt.description"] = "White as a lightning flash, and briefly blinding when it twists."
L["variety.13757.white-bolt.name"] = "White Bolt"
L["variety.13758.cinder.description"] = "Ash-grey with glowing red gills, like a coal pulled from a dead fire."
L["variety.13758.cinder.name"] = "Cinder"
L["variety.13758.ember-gilled.description"] = "Barred like a perch, with gills red as embers. The usual look, and the usual temper."
L["variety.13758.ember-gilled.name"] = "Ember-gilled"
L["variety.13758.fel-scarred.description"] = "Green fire runs under the scales where its red should be. It came from water that remembers a corruption."
L["variety.13758.fel-scarred.name"] = "Fel-scarred"
L["variety.13758.fire-gilled.description"] = "The gills actually glow. Nobody's sure the water was cold enough."
L["variety.13758.fire-gilled.name"] = "Fire-gilled"
L["variety.13758.ghost.description"] = "Pale, with pink gills and faint bars. Feels cold even in summer."
L["variety.13758.ghost.name"] = "Ghost"
L["variety.13758.golden.description"] = "Gold with scarlet gills. Looks like something from a lord's fountain."
L["variety.13758.golden.name"] = "Golden"
L["variety.13758.olive.description"] = "Darker olive, from overgrown rivers. The gills shine brighter by contrast."
L["variety.13758.olive.name"] = "Olive"
L["variety.13758.redfin.description"] = "Fins as red as the gills. The whole fish looks angry, because it is."
L["variety.13758.redfin.name"] = "Redfin"
L["variety.13758.spotted.description"] = "Spots instead of bars. Same temper."
L["variety.13758.spotted.name"] = "Spotted"
L["variety.13758.yellow.description"] = "Yellow-gold with dark bars. Bright as a lamp in green water."
L["variety.13758.yellow.name"] = "Yellow"
L["variety.13759.crescent-marked.description"] = "A pale crescent on each flank, as if the moon left a fingerprint."
L["variety.13759.crescent-marked.name"] = "Crescent-marked"
L["variety.13759.dawn-caught.description"] = "Pink and gold, caught as the night ended. A night fish that stayed up too late."
L["variety.13759.dawn-caught.name"] = "Dawn-caught"
L["variety.13759.dusk.description"] = "Violet back, rose belly, like the sky just after sunset."
L["variety.13759.dusk.name"] = "Dusk"
L["variety.13759.eclipse.description"] = "Black, rimmed with gold at the fins, like the sun gone dark."
L["variety.13759.eclipse.name"] = "Eclipse"
L["variety.13759.indigo.description"] = "Deep indigo. Vanishes in the water as soon as the moon goes in."
L["variety.13759.indigo.name"] = "Indigo"
L["variety.13759.moonfin.description"] = "Silver-white fins that catch the moonlight. Anglers learn to like the dark."
L["variety.13759.moonfin.name"] = "Moonfin"
L["variety.13759.owl-eyed.description"] = "Huge golden eyes made for the dark. Stares right back."
L["variety.13759.owl-eyed.name"] = "Owl-eyed"
L["variety.13759.star-speckled.description"] = "Pale specks along the back, like a sky with a few stars out."
L["variety.13759.star-speckled.name"] = "Star-speckled"
L["variety.13759.starfeeder.description"] = "Dark violet with fins like the night. Feeds by starlight."
L["variety.13759.starfeeder.name"] = "Starfeeder"
L["variety.13759.starsong.description"] = "Its specks shine like the night sky and move as it turns, like stars wheeling. Silence falls on the dock."
L["variety.13759.starsong.name"] = "Starsong"
L["variety.13760.coin-scaled.description"] = "Silver with gold-flecked scales that catch the light like coins in a stream."
L["variety.13760.coin-scaled.name"] = "Coin-scaled"
L["variety.13760.copper.description"] = "Polished copper from head to tail. Tastes like salmon, looks like a kettle."
L["variety.13760.copper.name"] = "Copper"
L["variety.13760.hooknose.description"] = "A fierce hooked jaw from its run upriver. Looks ready to fight a bear."
L["variety.13760.hooknose.name"] = "Hooknose"
L["variety.13760.morning.description"] = "Flushed peach along the belly, like first light on a river."
L["variety.13760.morning.name"] = "Morning"
L["variety.13760.noonday.description"] = "Gold all along the back, like a river at noon."
L["variety.13760.noonday.name"] = "Noonday"
L["variety.13760.red-run.description"] = "Gone red for the spawning run, with a green head. The river turns red with them in a good year."
L["variety.13760.red-run.name"] = "Red Run"
L["variety.13760.river-dark.description"] = "Darker, from shaded rivers. The gold flecks stand out."
L["variety.13760.river-dark.name"] = "River-dark"
L["variety.13760.silverbright.description"] = "Bright silver, fresh from the sea. Barely a fleck of gold."
L["variety.13760.silverbright.name"] = "Silverbright"
L["variety.13760.sunfire.description"] = "Every scale lit gold like a tiny sun. Warm as a hearthstone. Hard to look at directly."
L["variety.13760.sunfire.name"] = "Sunfire"
L["variety.13760.twilight.description"] = "Violet and orange, like the last light on the river. Gone by full dark."
L["variety.13760.twilight.name"] = "Twilight"
L["variety.13888.abyssal.description"] = "Violet light glows from the joints of its shell. Climbed up from very deep water, and seems annoyed about it."
L["variety.13888.abyssal.name"] = "Abyssal"
L["variety.13888.barnacled.description"] = "Barnacles all over the shell. Hasn't moulted in a long while, and isn't sorry."
L["variety.13888.barnacled.name"] = "Barnacled"
L["variety.13888.bigclaw.description"] = "One claw twice the size of the other. Knows exactly which one to use."
L["variety.13888.bigclaw.name"] = "Bigclaw"
L["variety.13888.blue-black.description"] = "Blue-black shell, lightly speckled, claws first. The kind that hides under every rock in the bay."
L["variety.13888.blue-black.name"] = "Blue-black"
L["variety.13888.calico.description"] = "Orange and black in patches, like a tortoiseshell cat. Hardly anyone believes it."
L["variety.13888.calico.name"] = "Calico"
L["variety.13888.ghost.description"] = "White as bone. Even the claws are pale. Even the temper isn't."
L["variety.13888.ghost.name"] = "Ghost"
L["variety.13888.mud-brown.description"] = "Brown from muddy shelves. Pinches just as hard."
L["variety.13888.mud-brown.name"] = "Mud-brown"
L["variety.13888.red-banded.description"] = "Red bands across the tail. Looks half-cooked already. Isn't."
L["variety.13888.red-banded.name"] = "Red-banded"
L["variety.13888.sapphire.description"] = "Bright blue all over. One in a great many. Pinches like the rest."
L["variety.13888.sapphire.name"] = "Sapphire"
L["variety.13888.sea-green.description"] = "Green-black, like a lobster of colder seas."
L["variety.13888.sea-green.name"] = "Sea-green"
L["variety.13889.ashen.description"] = "Grey as ash, from waters near the blighted lands. Still fine eating, they say."
L["variety.13889.ashen.name"] = "Ashen"
L["variety.13889.crystal.description"] = "Clear as ice in places. The pan seems wrong somehow."
L["variety.13889.crystal.name"] = "Crystal"
L["variety.13889.frost-white.description"] = "Pale silver, lightly speckled, cold to the touch however long it sits in the sun."
L["variety.13889.frost-white.name"] = "Frost-white"
L["variety.13889.hooknose.description"] = "A hooked jaw and a cold stare. Frost on the whiskers that it doesn't have."
L["variety.13889.hooknose.name"] = "Hooknose"
L["variety.13889.hot-spring.description"] = "Warmer-toned, from waters where the springs rise. Steam comes off it when landed."
L["variety.13889.hot-spring.name"] = "Hot-spring"
L["variety.13889.pearl.description"] = "A pearly sheen with no spots at all. Looks carved."
L["variety.13889.pearl.name"] = "Pearl"
L["variety.13889.silverblue.description"] = "A blue cast along the back, from glacier water."
L["variety.13889.silverblue.name"] = "Silverblue"
L["variety.13889.snowflake.description"] = "Bright white spots on silver, like snow on a frozen lake."
L["variety.13889.snowflake.name"] = "Snowflake"
L["variety.13889.spawn-blush.description"] = "A pink blush along the flanks for spawning. Rare in such cold water."
L["variety.13889.spawn-blush.name"] = "Spawn-blush"
L["variety.13889.wintersheen.description"] = "Frost patterns cover every scale and glow faintly blue. It never thaws, not even in the pan."
L["variety.13889.wintersheen.name"] = "Wintersheen"
L["variety.13890.ancient-bulwark.description"] = "Plates thick as shields, carved with old lines that glow gold. As if somebody forged it long ago and set it swimming."
L["variety.13890.ancient-bulwark.name"] = "Ancient Bulwark"
L["variety.13890.battle-scarred.description"] = "Dented plates and old gouges. Whatever tried to eat it gave up."
L["variety.13890.battle-scarred.name"] = "Battle-scarred"
L["variety.13890.bony-backed.description"] = "Bony plates down the back like a sturgeon. Wears its armour outside, temper inside."
L["variety.13890.bony-backed.name"] = "Bony-backed"
L["variety.13890.bronze-plated.description"] = "Plates the colour of old bronze. Looks fit for a parade."
L["variety.13890.bronze-plated.name"] = "Bronze-plated"
L["variety.13890.gilded.description"] = "Gold-edged plates, like a knight's parade armour. Fights like a knight, too."
L["variety.13890.gilded.name"] = "Gilded"
L["variety.13890.iron-plated.description"] = "Grey plates like iron armour. Bring a heavier knife."
L["variety.13890.iron-plated.name"] = "Iron-plated"
L["variety.13890.moss-backed.description"] = "Green moss on its plates. Hasn't moved in a while, then suddenly has."
L["variety.13890.moss-backed.name"] = "Moss-backed"
L["variety.13890.ore-plated.description"] = "Plates with a green-grey shine, like the hardest ore in the mountains. The knife gives up first."
L["variety.13890.ore-plated.name"] = "Ore-plated"
L["variety.13890.ring-plated.description"] = "Plates in neat rings, like a coat of banded mail."
L["variety.13890.ring-plated.name"] = "Ring-plated"
L["variety.13890.spiked.description"] = "Every plate tipped with a spike. Sensible anglers use the net."
L["variety.13890.spiked.name"] = "Spiked"
L["variety.13893.abyss-dark.description"] = "Black-blue, from the deepest trench of the bay. Tugs like the trench wants it back."
L["variety.13893.abyss-dark.name"] = "Abyss-dark"
L["variety.13893.barred.description"] = "Broad dark bars down its sides like ribs on a ship's hull."
L["variety.13893.barred.name"] = "Barred"
L["variety.13893.big-blue.description"] = "Huge, blue and broad. Both hands, and probably a friend."
L["variety.13893.big-blue.name"] = "Big Blue"
L["variety.13893.golden.description"] = "A golden giant. Nobody believes the story without the fish."
L["variety.13893.golden.name"] = "Golden"
L["variety.13893.hump-shouldered.description"] = "A great hump behind the head. Built like a dock piling."
L["variety.13893.hump-shouldered.name"] = "Hump-shouldered"
L["variety.13893.leviathans-get.description"] = "Glowing lines like old runes along its flanks. The bay's oldest stories are about something bigger than this. It's a start."
L["variety.13893.leviathans-get.name"] = "Leviathan's Get"
L["variety.13893.old-scarback.description"] = "Scars from teeth bigger than any angler wants to meet."
L["variety.13893.old-scarback.name"] = "Old Scarback"
L["variety.13893.sea-green.description"] = "Green as deep water. Takes three to pull it into the boat."
L["variety.13893.sea-green.name"] = "Sea-green"
L["variety.13893.spotted.description"] = "Pale spots across a dark back like foam on a wave."
L["variety.13893.spotted.name"] = "Spotted"
L["variety.13893.storm-grey.description"] = "Grey as the bay in a storm. Feels like it weighs as much."
L["variety.13893.storm-grey.name"] = "Storm-grey"
L["variety.1467.barred.description"] = "Faint bars down the flanks, the way the young wear them. Some never grow out of it."
L["variety.1467.barred.name"] = "Barred"
L["variety.1467.blue-cheeked.description"] = "Two blue lines on each cheek, like war paint for a very small war."
L["variety.1467.blue-cheeked.name"] = "Blue-cheeked"
L["variety.1467.copper-breasted.description"] = "A breast like a polished kettle. The cooks hesitate, briefly."
L["variety.1467.copper-breasted.name"] = "Copper-breasted"
L["variety.1467.ember-spotted.description"] = "The spots run red in the warm months, as if it sat too close to the fire."
L["variety.1467.ember-spotted.name"] = "Ember-spotted"
L["variety.1467.golden.description"] = "All the green gone, only gold left. Herons see it from across the lake."
L["variety.1467.golden.name"] = "Golden"
L["variety.1467.midnight.description"] = "Black as lake mud, spots and all. Easy to miss, which is rather the point."
L["variety.1467.midnight.name"] = "Midnight"
L["variety.1467.pale-shallows.description"] = "Bleached by warm shallows and long afternoons. The spots barely bother."
L["variety.1467.pale-shallows.name"] = "Pale Shallows"
L["variety.1467.peppered.description"] = "Spots ground down to pepper. Same fish, finer seasoning."
L["variety.1467.peppered.name"] = "Peppered"
L["variety.1467.sunburst.description"] = "Orange rays run out from the eye like morning over still water. It stays warm in the hand."
L["variety.1467.sunburst.name"] = "Sunburst"
L["variety.1467.sunset-breasted.description"] = "Olive flanks, dark spots, a breast like a sunset over the lake. The one everybody knows."
L["variety.1467.sunset-breasted.name"] = "Sunset-breasted"
L["variety.16967.feeding-barred.description"] = "Pale bars flash on its flanks, as tuna show when hunting. Caught mid-meal."
L["variety.16967.feeding-barred.name"] = "Feeding-barred"
L["variety.16967.ghostfin.description"] = "Pale all over, the fins almost clear. Swims like a reflection."
L["variety.16967.ghostfin.name"] = "Ghostfin"
L["variety.16967.gold-belted.description"] = "A gold stripe from eye to tail. A favour fish in its finest clothes."
L["variety.16967.gold-belted.name"] = "Gold-belted"
L["variety.16967.imperial.description"] = "Deep royal blue with fins of bright gold. Looks too fine to be a favour for anybody."
L["variety.16967.imperial.name"] = "Imperial"
L["variety.16967.leaf-lit.description"] = "Pale green light moves under its scales like sun through leaves. The forest's old magic is in these waters."
L["variety.16967.leaf-lit.name"] = "Leaf-lit"
L["variety.16967.mossback.description"] = "Green-black above, as if the forest grew on it. Swims slow, then very fast."
L["variety.16967.mossback.name"] = "Mossback"
L["variety.16967.sickle-fin.description"] = "Fins grown long and curved like sickles. Built for long journeys downriver."
L["variety.16967.sickle-fin.name"] = "Sickle-fin"
L["variety.16967.silverflank.description"] = "Brighter silver all down the side. The yellow fins look painted on."
L["variety.16967.silverflank.name"] = "Silverflank"
L["variety.16967.verdant.description"] = "A green cast along the back, from river water under the great trees."
L["variety.16967.verdant.name"] = "Verdant"
L["variety.16967.yellowfin.description"] = "Dark blue back, silver belly, long yellow fins. The fish the river is famous for."
L["variety.16967.yellowfin.name"] = "Yellowfin"
L["variety.16968.blackback.description"] = "Black above, steel below. Strikes from the dark."
L["variety.16968.blackback.name"] = "Blackback"
L["variety.16968.bonecutter.description"] = "Teeth like bone saws and a back covered in old marks. Dry-coast stories say it outlived three hunters."
L["variety.16968.bonecutter.name"] = "Bonecutter"
L["variety.16968.bronze.description"] = "Bronze-barred, from warm water. Twice the temper."
L["variety.16968.bronze.name"] = "Bronze"
L["variety.16968.chevron.description"] = "Dark chevrons down its back like arrows pointing at trouble."
L["variety.16968.chevron.name"] = "Chevron"
L["variety.16968.ghost.description"] = "White and nearly clear, the bars a shadow of themselves. The teeth are perfectly solid."
L["variety.16968.ghost.name"] = "Ghost"
L["variety.16968.greyback.description"] = "Plain grey above, white below. Just teeth and intent."
L["variety.16968.greyback.name"] = "Greyback"
L["variety.16968.needlejaw.description"] = "Teeth like a row of needles. Count your fingers after."
L["variety.16968.needlejaw.name"] = "Needlejaw"
L["variety.16968.sandstrand.description"] = "Sand-coloured, from the shallows of a dry coast. Invisible until it strikes."
L["variety.16968.sandstrand.name"] = "Sandstrand"
L["variety.16968.silver-barred.description"] = "Long, silver and barred, with a jaw full of teeth. Built for one thing."
L["variety.16968.silver-barred.name"] = "Silver-barred"
L["variety.16968.spotted.description"] = "Black spots near the tail, as the big ones grow. Still waiting for an argument."
L["variety.16968.spotted.name"] = "Spotted"
L["variety.16969.barred.description"] = "Pale blue bars down the flanks, lit up mid-fight. Best seen in the air, which is where it spends the fight."
L["variety.16969.barred.name"] = "Barred"
L["variety.16969.jungle-green.description"] = "Green as the jungle behind the coast. Shows off just the same."
L["variety.16969.jungle-green.name"] = "Jungle-green"
L["variety.16969.royal.description"] = "Deep royal blue, the sail spotted gold. Anglers take turns holding it."
L["variety.16969.royal.name"] = "Royal"
L["variety.16969.silver.description"] = "Silver more than blue. The sail stays bright as ever."
L["variety.16969.silver.name"] = "Silver"
L["variety.16969.skyleaper.description"] = "Lines of blue light ripple up the sail as it leaps. Seems to hang in the air longer than any fish should."
L["variety.16969.skyleaper.name"] = "Skyleaper"
L["variety.16969.spotted-sail.description"] = "Blue back, silver belly, a tall sail dotted with spots. Raises it the moment anyone watches."
L["variety.16969.spotted-sail.name"] = "Spotted Sail"
L["variety.16969.sunset-sail.description"] = "An orange sail, like the coast at evening. Leaps more than the blue ones."
L["variety.16969.sunset-sail.name"] = "Sunset Sail"
L["variety.16969.tall-sailed.description"] = "A sail taller than the fish is deep. Wind catches it on the line."
L["variety.16969.tall-sailed.name"] = "Tall-sailed"
L["variety.16969.violet-sail.description"] = "The sail glows violet when it's excited. It's always excited."
L["variety.16969.violet-sail.name"] = "Violet Sail"
L["variety.16969.white-sail.description"] = "Pale as a ship's canvas. Sailors swear it's a sign of good weather."
L["variety.16969.white-sail.name"] = "White Sail"
L["variety.16970.barred.description"] = "Dark bars flash on its sides when hooked. It's furious."
L["variety.16970.barred.name"] = "Barred"
L["variety.16970.bluefin.description"] = "Blue along the back and fins. Cooler-headed. Not by much."
L["variety.16970.bluefin.name"] = "Bluefin"
L["variety.16970.bull-headed.description"] = "A blunt, tall forehead like a bull mahi. Charges the boat."
L["variety.16970.bull-headed.name"] = "Bull-headed"
L["variety.16970.dorado.description"] = "Green and gold with blue spots, like a parrot that took up swimming."
L["variety.16970.dorado.name"] = "Dorado"
L["variety.16970.emerald.description"] = "Pure green, no gold at all. Like a gem dropped in the marsh."
L["variety.16970.emerald.name"] = "Emerald"
L["variety.16970.fog-pale.description"] = "Pale, as if the swamp mist got into the colour. Fights like a fog bank, then like a mule."
L["variety.16970.fog-pale.name"] = "Fog-pale"
L["variety.16970.gold-flanked.description"] = "More gold than green. Fades to grey soon after landing, so look quickly."
L["variety.16970.gold-flanked.name"] = "Gold-flanked"
L["variety.16970.marsh-lantern.description"] = "Its spots glow green-gold in the mist, like lanterns in a swamp. Locals say it leads anglers astray."
L["variety.16970.marsh-lantern.name"] = "Marsh Lantern"
L["variety.16970.reed-green.description"] = "Dull green, from the misty reeds. Hard to see until it jumps."
L["variety.16970.reed-green.name"] = "Reed-green"
L["variety.16970.sunfire.description"] = "Orange and gold, like a fire at the water's edge. The swamp goes quiet to look."
L["variety.16970.sunfire.name"] = "Sunfire"
L["variety.19807.big-spotted.description"] = "Spots like thrown coins. Somebody always claims it's a different fish."
L["variety.19807.big-spotted.name"] = "Big-spotted"
L["variety.19807.black.description"] = "Black with white freckles, like a night sky in a hurry."
L["variety.19807.black.name"] = "Black"
L["variety.19807.champions.description"] = "Every freckle shines like a gold coin. The kind of fish that gets its own story told for years."
L["variety.19807.champions.name"] = "Champion's"
L["variety.19807.contest-speckle.description"] = "Silvery-grey and freckled. Every contestant on the dock knows this one by sight."
L["variety.19807.contest-speckle.name"] = "Contest Speckle"
L["variety.19807.gilded.description"] = "Gold with brown freckles. A crowd gathers on the dock."
L["variety.19807.gilded.name"] = "Gilded"
L["variety.19807.lucky-speckle.description"] = "One speckle shaped like a horseshoe. Kept for luck, then eaten for lunch."
L["variety.19807.lucky-speckle.name"] = "Lucky Speckle"
L["variety.19807.olive.description"] = "Green-backed, from weedy shallows. Contestants grab them anyway."
L["variety.19807.olive.name"] = "Olive"
L["variety.19807.pale.description"] = "White with faint cream freckles. Turns heads at every contest."
L["variety.19807.pale.name"] = "Pale"
L["variety.19807.red-speckled.description"] = "Red freckles. Looks seasoned already."
L["variety.19807.red-speckled.name"] = "Red-speckled"
L["variety.19807.silver-speckle.description"] = "Brighter silver, from open water. Same freckles."
L["variety.19807.silver-speckle.name"] = "Silver Speckle"
L["variety.19975.bloodmud.description"] = "Dark red, from mud where old offerings were made. Best not asked about."
L["variety.19975.bloodmud.name"] = "Bloodmud"
L["variety.19975.idol-touched.description"] = "Faint red-violet veins glow on its back like old idol paint. Even the beasts of these waters keep clear of it."
L["variety.19975.idol-touched.name"] = "Idol-touched"
L["variety.19975.jungle-mud.description"] = "Green-brown, from deep jungle mud. Smells of it, too."
L["variety.19975.jungle-mud.name"] = "Jungle-mud"
L["variety.19975.long-whiskered.description"] = "Long barbels that trail in the mud. Finds every bait, smells every one."
L["variety.19975.long-whiskered.name"] = "Long-whiskered"
L["variety.19975.masked.description"] = "A dark band across the eyes like a carved mask. Looks like it knows things."
L["variety.19975.masked.name"] = "Masked"
L["variety.19975.ochre.description"] = "Ochre-yellow, like the clay the trolls paint with. Smells no better."
L["variety.19975.ochre.name"] = "Ochre"
L["variety.19975.pale.description"] = "Bone-pale, from water under ancient stone. The smell survives the colour."
L["variety.19975.pale.name"] = "Pale"
L["variety.19975.skunk-striped.description"] = "A pale stripe from head to tail. A warning, and a fair one."
L["variety.19975.skunk-striped.name"] = "Skunk-striped"
L["variety.19975.slimeback.description"] = "Brown, slimy and squat. The nose finds it before the eyes do."
L["variety.19975.slimeback.name"] = "Slimeback"
L["variety.19975.spotted.description"] = "Dark spots on brown, like mud splashed on mud."
L["variety.19975.spotted.name"] = "Spotted"
L["variety.21071.banded.description"] = "Faint bands like rows in a herb garden."
L["variety.21071.banded.name"] = "Banded"
L["variety.21071.dark-sage.description"] = "Deep green, from shaded streams. Smells stronger."
L["variety.21071.dark-sage.name"] = "Dark Sage"
L["variety.21071.frost-sage.description"] = "Pale with a frosted edge to every scale. Tastes cleaner, somehow."
L["variety.21071.frost-sage.name"] = "Frost Sage"
L["variety.21071.gold-sage.description"] = "Yellow-green like dry summer grass. Smells of a long hot day."
L["variety.21071.gold-sage.name"] = "Gold Sage"
L["variety.21071.hillside.description"] = "Sage-green and freckled, like the hills above the stream it came from."
L["variety.21071.hillside.name"] = "Hillside"
L["variety.21071.lavender-finned.description"] = "Fins the colour of lavender. Smells, faintly, of it too."
L["variety.21071.lavender-finned.name"] = "Lavender-finned"
L["variety.21071.mindbright.description"] = "Pale light flickers in the lines of its scales. Anglers who eat it say they think more clearly. They say that a lot."
L["variety.21071.mindbright.name"] = "Mindbright"
L["variety.21071.silver-sage.description"] = "Silvery, like sage leaves turned over in the wind."
L["variety.21071.silver-sage.name"] = "Silver Sage"
L["variety.21071.sweetgrass.description"] = "Bright green and sweet-smelling. The only fish anybody has wanted to put in a drawer with the linen."
L["variety.21071.sweetgrass.name"] = "Sweetgrass"
L["variety.21071.thyme-spotted.description"] = "Tiny purple spots like thyme flowers. The cooks approve."
L["variety.21071.thyme-spotted.name"] = "Thyme-spotted"
L["variety.21153.ashen.description"] = "Grey as smoke, and it smells faintly of incense. Nobody burns sage near the water any more."
L["variety.21153.ashen.name"] = "Ashen"
L["variety.21153.banded.description"] = "Broad bands like the rings of a tree. The old ones have more."
L["variety.21153.banded.name"] = "Banded"
L["variety.21153.bearded.description"] = "Long trailing fins like an old sage's beard. Looks wiser than it is."
L["variety.21153.bearded.name"] = "Bearded"
L["variety.21153.bronze.description"] = "Bronze from tannin-dark rivers. Tastes faintly of tea."
L["variety.21153.bronze.name"] = "Bronze"
L["variety.21153.elder-sage.description"] = "Old, huge, its scales lit with pale gold lines like veins in a leaf. Some places keep their oldest things."
L["variety.21153.elder-sage.name"] = "Elder Sage"
L["variety.21153.full-grown.description"] = "The sage grew up: bigger, darker, still fragrant."
L["variety.21153.full-grown.name"] = "Full-grown"
L["variety.21153.golden.description"] = "Gold and fragrant. Smells like honey on warm stone."
L["variety.21153.golden.name"] = "Golden"
L["variety.21153.moss-green.description"] = "Mottled like moss on old stone. Smells of a damp forest."
L["variety.21153.moss-green.name"] = "Moss-green"
L["variety.21153.silver.description"] = "A silver giant of its kind. Grew up and got bright."
L["variety.21153.silver.name"] = "Silver"
L["variety.21153.violet-finned.description"] = "Purple fins, like a sage in bloom. The scent is stronger in spring."
L["variety.21153.violet-finned.name"] = "Violet-finned"
L["variety.251524.dreamfin.description"] = "Glows soft pink and blue, and leaves a faint shimmer in the water behind it. Small children are told it grants wishes. Nobody checks."
L["variety.251524.dreamfin.name"] = "Dreamfin"
L["variety.251524.frill-finned.description"] = "Fins like lace ruffles. Hopeless at swimming, delighted anyway."
L["variety.251524.frill-finned.name"] = "Frill-finned"
L["variety.251524.lemon.description"] = "Lemon yellow with blue dots. It seems very pleased about something."
L["variety.251524.lemon.name"] = "Lemon"
L["variety.251524.lilac.description"] = "Lilac with cream stripes. Swims in loops, for no clear reason."
L["variety.251524.lilac.name"] = "Lilac"
L["variety.251524.mint.description"] = "Mint green with pink dots. Looks like a sweet from a fair."
L["variety.251524.mint.name"] = "Mint"
L["variety.251524.murk-touched.description"] = "Dark purple, its dots dimmed. The only one of its kind that looks like it has had a bad day."
L["variety.251524.murk-touched.name"] = "Murk-touched"
L["variety.251524.polka-dotted.description"] = "Big white dots on pink, like a festival dress. It knows."
L["variety.251524.polka-dotted.name"] = "Polka-dotted"
L["variety.251524.rainbow.description"] = "Every colour in stripes, as if painted by a child with a full box. It glitters."
L["variety.251524.rainbow.name"] = "Rainbow"
L["variety.251524.swirled.description"] = "Pink and blue swirled together like icing. Makes anglers hungry for the wrong thing."
L["variety.251524.swirled.name"] = "Swirled"
L["variety.251524.whimsical.description"] = "Gold, with flowing blue fins like a dancer's scarves. Looks painted by somebody in a very good mood."
L["variety.251524.whimsical.name"] = "Whimsical"
L["variety.4603.all-gold.description"] = "Yellow from tail to nose. Gulls follow the boat for miles."
L["variety.4603.all-gold.name"] = "All-gold"
L["variety.4603.classic.description"] = "Blue-grey back, yellow tail, a scatter of dark spots. The look every coastal cook expects."
L["variety.4603.classic.name"] = "Classic"
L["variety.4603.dusky.description"] = "Dark from deep water, the yellow dulled to old brass."
L["variety.4603.dusky.name"] = "Dusky"
L["variety.4603.ghost.description"] = "Nearly white, with a faint yellow blush at the tail. Looks underwater even out of it."
L["variety.4603.ghost.name"] = "Ghost"
L["variety.4603.gold-striped.description"] = "A yellow line runs nose to tail, as if somebody underlined it."
L["variety.4603.gold-striped.name"] = "Gold-striped"
L["variety.4603.greenback.description"] = "Greener along the back, from weedy coasts. The tail stays proudly yellow."
L["variety.4603.greenback.name"] = "Greenback"
L["variety.4603.leopard.description"] = "The spots grew greedy and joined up. Handsome, in a crowded way."
L["variety.4603.leopard.name"] = "Leopard"
L["variety.4603.silverside.description"] = "More mirror than fish down the flanks. Spots few and shy."
L["variety.4603.silverside.name"] = "Silverside"
L["variety.4603.sunset-tailed.description"] = "The tail burns orange instead of yellow. Even prouder of itself, if that were possible."
L["variety.4603.sunset-tailed.name"] = "Sunset-tailed"
L["variety.4603.tidecaller.description"] = "Fine blue netting glows along its flanks. Old sailors say the tide turns when one is landed."
L["variety.4603.tidecaller.name"] = "Tidecaller"
L["variety.6289.blackjaw.description"] = "The jaw is ink-dark to the gills. It has opinions and it shares them."
L["variety.6289.blackjaw.name"] = "Blackjaw"
L["variety.6289.brindle.description"] = "Streaked like a hound's coat. Some anglers swear it growls."
L["variety.6289.brindle.name"] = "Brindle"
L["variety.6289.golden.description"] = "A gold snapper from a brown pond. The pond seems as surprised as anyone."
L["variety.6289.golden.name"] = "Golden"
L["variety.6289.lantern-eyed.description"] = "Eyes that catch the light like a lamp in a window. Easier to find at dusk."
L["variety.6289.lantern-eyed.name"] = "Lantern-eyed"
L["variety.6289.mudbank.description"] = "Brown above, tan below, jaw first. The snapper every pond in the world seems to have."
L["variety.6289.mudbank.name"] = "Mudbank"
L["variety.6289.old-bootbiter.description"] = "Hook scars, a torn fin and an expression of total confidence. Every pond keeps one."
L["variety.6289.old-bootbiter.name"] = "Old Bootbiter"
L["variety.6289.pale.description"] = "Milk-pale, pink at the fins. Too pretty for the jaw it carries."
L["variety.6289.pale.name"] = "Pale"
L["variety.6289.red-clay.description"] = "Rust-red, from riverbanks of red clay. Tastes the same, looks hotter."
L["variety.6289.red-clay.name"] = "Red Clay"
L["variety.6289.reedbed.description"] = "Faint green bars, from hiding among the reeds. Still bites first."
L["variety.6289.reedbed.name"] = "Reedbed"
L["variety.6289.speckled.description"] = "Freckled all over, like a farmhand after harvest."
L["variety.6289.speckled.name"] = "Speckled"
L["variety.6291.blue-striped.description"] = "A neat blue stripe down each side, as if it were trying to look official."
L["variety.6291.blue-striped.name"] = "Blue-striped"
L["variety.6291.dotted.description"] = "A row of small dots along the flank, neat as stitching."
L["variety.6291.dotted.name"] = "Dotted"
L["variety.6291.glass.description"] = "You can see its backbone. It can probably see yours."
L["variety.6291.glass.name"] = "Glass"
L["variety.6291.golden.description"] = "A gold coin with fins. Children want to keep it. Anglers want to keep it too."
L["variety.6291.golden.name"] = "Golden"
L["variety.6291.greenback.description"] = "Green across the back, from shallow weedy water. Twice as hard to spot."
L["variety.6291.greenback.name"] = "Greenback"
L["variety.6291.inkfin.description"] = "Dark as a quill's tip. Swims with the bright ones and fools nobody."
L["variety.6291.inkfin.name"] = "Inkfin"
L["variety.6291.rainbow.description"] = "Throws colours like a soap bubble when it turns. Gone grey once landed."
L["variety.6291.rainbow.name"] = "Rainbow"
L["variety.6291.redfin.description"] = "Fins dipped in red. Shows off in a school, rarely alone."
L["variety.6291.redfin.name"] = "Redfin"
L["variety.6291.silver.description"] = "Plain silver, flashing in the shallows by the hundred. The first fish in a great many books."
L["variety.6291.silver.name"] = "Silver"
L["variety.6291.starlit.description"] = "Tiny pale specks glow along its back like a clear night. Remarkable, for something this small."
L["variety.6291.starlit.name"] = "Starlit"
L["variety.6299.ashen.description"] = "Grey to the bone, like it swam through ash. Even the flies keep their distance."
L["variety.6299.ashen.name"] = "Ashen"
L["variety.6299.bilious.description"] = "Yellow-green, like a bad morning. Handle with gloves."
L["variety.6299.bilious.name"] = "Bilious"
L["variety.6299.blighted.description"] = "Faint green veins glow under the scales. Some waters remember what was spilled in them."
L["variety.6299.blighted.name"] = "Blighted"
L["variety.6299.blotchy.description"] = "Covered in sad brown blotches. Nobody asks what caused them."
L["variety.6299.blotchy.name"] = "Blotchy"
L["variety.6299.bony.description"] = "More ribs than fish. It tried its best."
L["variety.6299.bony.name"] = "Bony"
L["variety.6299.bruised.description"] = "Purple and blue in patches, as if it lost a fight with the current."
L["variety.6299.bruised.name"] = "Bruised"
L["variety.6299.greenish.description"] = "Patches of green that should not be there. The smell arrives before the fish does."
L["variety.6299.greenish.name"] = "Greenish"
L["variety.6299.greyish.description"] = "Grey, limp and faintly apologetic. It looks bad and smells worse."
L["variety.6299.greyish.name"] = "Greyish"
L["variety.6299.recovered.description"] = "Healthier than the rest. Still unmistakably one of them, somehow."
L["variety.6299.recovered.name"] = "Recovered"
L["variety.6299.wheezing.description"] = "Gills flap in a way that sounds almost like a sigh. It knows."
L["variety.6299.wheezing.name"] = "Wheezing"
L["variety.6303.blueback.description"] = "Bluer, from the open sea. Fries up just as well."
L["variety.6303.blueback.name"] = "Blueback"
L["variety.6303.bronze.description"] = "Bronze along the back like an old coin. Odd for a mackerel. It doesn't care."
L["variety.6303.bronze.name"] = "Bronze"
L["variety.6303.emerald.description"] = "Green as kelp, with a shimmer that fades within the hour."
L["variety.6303.emerald.name"] = "Emerald"
L["variety.6303.golden.description"] = "Gold bars on gold. Looks expensive. Fries like a mackerel."
L["variety.6303.golden.name"] = "Golden"
L["variety.6303.pearl.description"] = "White as a shell, the bars only a ghost of themselves. Lovely, and still slippery."
L["variety.6303.pearl.name"] = "Pearl"
L["variety.6303.plainback.description"] = "No bars at all. Slips through the hands faster without them, apparently."
L["variety.6303.plainback.name"] = "Plainback"
L["variety.6303.sea-witch.description"] = "Bars that glow sea-green in the dark. Sailors throw these back. Then they regret it."
L["variety.6303.sea-witch.name"] = "Sea-witch"
L["variety.6303.shallow-water.description"] = "Paler, from sandy bays near the shore. Still slithers."
L["variety.6303.shallow-water.name"] = "Shallow-water"
L["variety.6303.spotted.description"] = "Dots where the bars should be. Mackerel are not careful about the rules."
L["variety.6303.spotted.name"] = "Spotted"
L["variety.6303.tiger-backed.description"] = "Wavy dark bars across a blue-green back, like ripples frozen in place."
L["variety.6303.tiger-backed.name"] = "Tiger-backed"
L["variety.6308.albino.description"] = "White with pink eyes. Has clearly never seen the sun, and does not intend to."
L["variety.6308.albino.name"] = "Albino"
L["variety.6308.black-barbel.description"] = "Inky from whisker to tail. Swallows the light and most of the bait."
L["variety.6308.black-barbel.name"] = "Black Barbel"
L["variety.6308.calico.description"] = "Orange, white and black in patches, like a barn cat. Just as unimpressed."
L["variety.6308.calico.name"] = "Calico"
L["variety.6308.long-whiskered.description"] = "Whiskers twice the usual length. Wise-looking. Isn't."
L["variety.6308.long-whiskered.name"] = "Long-whiskered"
L["variety.6308.marbled.description"] = "Mottled like a riverbed, which is exactly where it spends its time."
L["variety.6308.marbled.name"] = "Marbled"
L["variety.6308.mudback.description"] = "Mud-brown above, cream below, whiskers everywhere. The catfish every river seems to keep."
L["variety.6308.mudback.name"] = "Mudback"
L["variety.6308.riverbed-king.description"] = "Whiskers thick as rope and a mouth like a cellar door. The river has been feeding it for years."
L["variety.6308.riverbed-king.name"] = "Riverbed King"
L["variety.6308.slate.description"] = "Blue-grey as river stone. Just as stubborn."
L["variety.6308.slate.name"] = "Slate"
L["variety.6308.spotted.description"] = "Dark spots along the flanks, like a channel catfish in its youth."
L["variety.6308.spotted.name"] = "Spotted"
L["variety.6308.yellowbelly.description"] = "A yellow belly and no shame about it. Fights anyway."
L["variety.6308.yellowbelly.name"] = "Yellowbelly"
L["variety.6317.ale-barred.description"] = "Amber bars like a well-poured ale. Dwarves name these fondly."
L["variety.6317.ale-barred.name"] = "Ale-barred"
L["variety.6317.blackwater.description"] = "Black as the bottom of a mine shaft. The teeth are white."
L["variety.6317.blackwater.name"] = "Blackwater"
L["variety.6317.dam-breaker.description"] = "Teeth like chisels and a jaw full of old splinters. Loch-side stories begin and end with this one."
L["variety.6317.dam-breaker.name"] = "Dam-Breaker"
L["variety.6317.ironjaw.description"] = "Jaw dark as old iron, and almost as hard. Gloves are advised."
L["variety.6317.ironjaw.name"] = "Ironjaw"
L["variety.6317.peat-stained.description"] = "Brown from peaty water. Tastes faintly of smoke."
L["variety.6317.peat-stained.name"] = "Peat-stained"
L["variety.6317.redbelly.description"] = "A belly red as a forge. The teeth are the same."
L["variety.6317.redbelly.name"] = "Redbelly"
L["variety.6317.ruby.description"] = "Red all over, like a gem in a miner's lamp. Somebody always tries to sell it."
L["variety.6317.ruby.name"] = "Ruby"
L["variety.6317.silverflank.description"] = "Bright silver flanks with a glitter of scales. Still all teeth."
L["variety.6317.silverflank.name"] = "Silverflank"
L["variety.6317.slate-backed.description"] = "Grey back, red belly, teeth. Named for how it behaves when held."
L["variety.6317.slate-backed.name"] = "Slate-backed"
L["variety.6317.snowmelt.description"] = "Pale from the coldest corner of the loch. Bites just as hard."
L["variety.6317.snowmelt.name"] = "Snowmelt"
L["variety.6358.black-gummed.description"] = "Black gums, spotted back, an oily sheen. Alchemists want the oil."
L["variety.6358.black-gummed.name"] = "Black-gummed"
L["variety.6358.bright-silver.description"] = "Fresh from open water and bright as a blade. The oil is there all the same."
L["variety.6358.bright-silver.name"] = "Bright Silver"
L["variety.6358.greenback.description"] = "Greener above, from kelp coasts. Just as oily."
L["variety.6358.greenback.name"] = "Greenback"
L["variety.6358.hooknose.description"] = "A hooked jaw from its spawning run. Looks offended at all times."
L["variety.6358.hooknose.name"] = "Hooknose"
L["variety.6358.lampblack.description"] = "Gold oil seeps along its scales and glows faintly. Lamp-makers would pay anything. They usually do."
L["variety.6358.lampblack.name"] = "Lampblack"
L["variety.6358.pearl.description"] = "White, with a pearly sheen from all that oil. Prettier than its reputation."
L["variety.6358.pearl.name"] = "Pearl"
L["variety.6358.rainbow-slicked.description"] = "The oil shows every colour in sunlight. Prettier than anything this greasy deserves."
L["variety.6358.rainbow-slicked.name"] = "Rainbow-slicked"
L["variety.6358.redflank.description"] = "Gone red along the flanks for spawning. Oilier than ever."
L["variety.6358.redflank.name"] = "Redflank"
L["variety.6358.spotless.description"] = "Not a single spot. The oil does the decorating."
L["variety.6358.spotless.name"] = "Spotless"
L["variety.6358.tar-black.description"] = "Black from mouth to tail and slick as tar. Leaves a mark on everything it touches."
L["variety.6358.tar-black.name"] = "Tar-black"
L["variety.6359.charred.description"] = "Black as a burnt log, fins still glowing red. Looks cooked. Isn't."
L["variety.6359.charred.name"] = "Charred"
L["variety.6359.coral.description"] = "Pinker, from reef water. A little cooler in the hand."
L["variety.6359.coral.name"] = "Coral"
L["variety.6359.deepwater.description"] = "Dark crimson from deep water. Holds the heat longer."
L["variety.6359.deepwater.name"] = "Deepwater"
L["variety.6359.ember-spotted.description"] = "Dark spots like cinders on red. Smells faintly of smoke when landed."
L["variety.6359.ember-spotted.name"] = "Ember-spotted"
L["variety.6359.flame-finned.description"] = "Red body, fins like flame. The colour most anglers picture when they hear the name."
L["variety.6359.flame-finned.name"] = "Flame-finned"
L["variety.6359.flame-striped.description"] = "Yellow lines run down it like flames up a wall."
L["variety.6359.flame-striped.name"] = "Flame-striped"
L["variety.6359.goldfin.description"] = "Fins of gold instead of red. Still warm."
L["variety.6359.goldfin.name"] = "Goldfin"
L["variety.6359.phoenix-fin.description"] = "Fins burn gold and the body glows like a forge. Water steams around it as it lands."
L["variety.6359.phoenix-fin.name"] = "Phoenix-fin"
L["variety.6359.smouldering.description"] = "Dark as a banked fire, red at the edges. Too warm to hold for long."
L["variety.6359.smouldering.name"] = "Smouldering"
L["variety.6359.white-flame.description"] = "White, with fins the pink of a hot coal. The heat is real."
L["variety.6359.white-flame.name"] = "White-flame"
L["variety.6361.aurora.description"] = "Colours ripple over it in waves, green to violet, and never fade. Nobody can explain why."
L["variety.6361.aurora.name"] = "Aurora"
L["variety.6361.barred.description"] = "Pale bars down the flanks, as albacore show when feeding hard."
L["variety.6361.barred.name"] = "Barred"
L["variety.6361.deep-blue.description"] = "Darker, from far offshore. The fins keep their colours a little longer."
L["variety.6361.deep-blue.name"] = "Deep Blue"
L["variety.6361.longfin.description"] = "Pectoral fins as long as a forearm. Swims like it owns the sea."
L["variety.6361.longfin.name"] = "Longfin"
L["variety.6361.many-hued.description"] = "Steel-blue back, silver belly, fins in every colour. They fade within the hour, so look quickly."
L["variety.6361.many-hued.name"] = "Many-hued"
L["variety.6361.prism.description"] = "White as sea-foam, every stripe a different colour. Holds them for a whole day."
L["variety.6361.prism.name"] = "Prism"
L["variety.6361.silverflank.description"] = "More silver than blue. The rainbow lives in the fins alone."
L["variety.6361.silverflank.name"] = "Silverflank"
L["variety.6361.stormback.description"] = "Grey as thunderheads, fins dulled to pewter. Bites best just before rain."
L["variety.6361.stormback.name"] = "Stormback"
L["variety.6361.sunset-finned.description"] = "Fins of orange and rose, like a sky at the end of a good day's fishing."
L["variety.6361.sunset-finned.name"] = "Sunset-finned"
L["variety.6361.violet.description"] = "A violet sheen along the back. Colours fade to a sulky grey after landing."
L["variety.6361.violet.name"] = "Violet"
L["variety.6362.barnacled.description"] = "Barnacles on its head, like an old hull. Has clearly been at this a long time."
L["variety.6362.barnacled.name"] = "Barnacled"
L["variety.6362.golden.description"] = "Gold mottling over gold. Looks like a statue someone forgot to finish."
L["variety.6362.golden.name"] = "Golden"
L["variety.6362.granite.description"] = "Black and white speckle like a millstone. Weighs as if it were one."
L["variety.6362.granite.name"] = "Granite"
L["variety.6362.harbour-grey.description"] = "Grey from harbour water. Just as sweet once cooked."
L["variety.6362.harbour-grey.name"] = "Harbour Grey"
L["variety.6362.kelp-green.description"] = "Green-brown from kelp beds. Pulls harder than it looks."
L["variety.6362.kelp-green.name"] = "Kelp-green"
L["variety.6362.leopard.description"] = "Bold dark spots on a sandy body. Stubborn even by cod standards."
L["variety.6362.leopard.name"] = "Leopard"
L["variety.6362.red-rock.description"] = "Rusty red, from red-rock coasts. Locals call it a different fish. It isn't."
L["variety.6362.red-rock.name"] = "Red Rock"
L["variety.6362.rock-mottled.description"] = "Mottled brown like the rocks it hides among, with a pale line down each flank."
L["variety.6362.rock-mottled.name"] = "Rock-mottled"
L["variety.6362.sandy.description"] = "Pale as a beach, fine-freckled. Shows up well on a plate."
L["variety.6362.sandy.name"] = "Sandy"
L["variety.6362.stoneheart.description"] = "Scales like slate, a faint glow between them. Found where the cliffs meet deep water, and nowhere else."
L["variety.6362.stoneheart.name"] = "Stoneheart"
L["variety.6458.black-gold.description"] = "Coated so thick it gleams like a polished boot. Prospectors take one look and start digging."
L["variety.6458.black-gold.name"] = "Black Gold"
L["variety.6458.half-clean.description"] = "The oil only got half of it. The other half looks quietly relieved."
L["variety.6458.half-clean.name"] = "Half-clean"
L["variety.6458.muddy.description"] = "More mud than oil. An improvement, of a sort."
L["variety.6458.muddy.name"] = "Muddy"
L["variety.6458.rainbow-slick.description"] = "The oil throws rainbows in the sun. A pretty sight, and a bad sign."
L["variety.6458.rainbow-slick.name"] = "Rainbow Slick"
L["variety.6458.rust-streaked.description"] = "Streaks of rust from old machine runoff. Very nearly a fish."
L["variety.6458.rust-streaked.name"] = "Rust-streaked"
L["variety.6458.slicked.description"] = "A small fish under a black coat of oil. Somewhere upstream, somebody is very busy."
L["variety.6458.slicked.name"] = "Slicked"
L["variety.6458.somehow-clean.description"] = "Clean, bright, healthy. It must have swum in from somewhere else."
L["variety.6458.somehow-clean.name"] = "Somehow Clean"
L["variety.6458.still-burning.description"] = "The oil on its back still smoulders, and nothing puts it out. Best not cooked indoors."
L["variety.6458.still-burning.name"] = "Still Burning"
L["variety.6458.sulphur-stained.description"] = "Yellow from something worse than oil. Smells like it, too."
L["variety.6458.sulphur-stained.name"] = "Sulphur-stained"
L["variety.6458.tarred.description"] = "Thick black tar in patches. Sticks to the line and the angler."
L["variety.6458.tarred.name"] = "Tarred"
L["variety.6522.crimson.description"] = "Red where it should be green. The stories about the hour after eating one get worse."
L["variety.6522.crimson.name"] = "Crimson"
L["variety.6522.dreamers-spawn.description"] = "Green light pulses beneath its scales, slow as breathing in sleep. The caverns' nightmare left its mark here."
L["variety.6522.dreamers-spawn.name"] = "Dreamer's Spawn"
L["variety.6522.glowgill.description"] = "Gills that glow faintly green. Reads as a warning, and it is."
L["variety.6522.glowgill.name"] = "Glowgill"
L["variety.6522.lizard-scaled.description"] = "Scales like a raptor's hide. Half fish, half something with opinions."
L["variety.6522.lizard-scaled.name"] = "Lizard-scaled"
L["variety.6522.many-eyed.description"] = "Eyespots all down the flanks. At least two of them blink."
L["variety.6522.many-eyed.name"] = "Many-eyed"
L["variety.6522.misshapen.description"] = "Green, lumpy and wrong in several places at once. Eat at your own risk."
L["variety.6522.misshapen.name"] = "Misshapen"
L["variety.6522.pale-nightmare.description"] = "Ghost-pale, organs faintly visible. Has the look of a bad dream at noon."
L["variety.6522.pale-nightmare.name"] = "Pale Nightmare"
L["variety.6522.purple-finned.description"] = "Fins of bruise-purple. Nobody agrees on whether that's better or worse."
L["variety.6522.purple-finned.name"] = "Purple-finned"
L["variety.6522.spined.description"] = "A ridge of spines down the back that weren't there yesterday."
L["variety.6522.spined.name"] = "Spined"
L["variety.6522.two-tailed.description"] = "Two tails, and it swims as if arguing with itself about which to use."
L["variety.6522.two-tailed.name"] = "Two-tailed"
L["variety.8365.bright-headed.description"] = "Olive body, freckled flanks, a head that shines like polished metal. The usual trout of warm rivers."
L["variety.8365.bright-headed.name"] = "Bright-headed"
L["variety.8365.brook-spotted.description"] = "Pale spots on olive, from cold quick streams."
L["variety.8365.brook-spotted.name"] = "Brook-spotted"
L["variety.8365.golden.description"] = "Gold all over, like the rare trout of high mountain lakes."
L["variety.8365.golden.name"] = "Golden"
L["variety.8365.goldhead.description"] = "Gold where the shine should be silver. The smith asks twice."
L["variety.8365.goldhead.name"] = "Goldhead"
L["variety.8365.ironhead.description"] = "Dark all over, the head like cast iron. Equally hard to cook."
L["variety.8365.ironhead.name"] = "Ironhead"
L["variety.8365.parr-marked.description"] = "Thumbprint marks down the flanks, as young trout wear. A late bloomer."
L["variety.8365.parr-marked.name"] = "Parr-marked"
L["variety.8365.quicksilver.description"] = "Silver from nose to tail, with a pale blue gleam. The smith finally has a case."
L["variety.8365.quicksilver.name"] = "Quicksilver"
L["variety.8365.rainbow-banded.description"] = "A pink band down the flank, as a rainbow trout wears it."
L["variety.8365.rainbow-banded.name"] = "Rainbow-banded"
L["variety.8365.red-spotted.description"] = "Red spots ringed in blue. Pretty enough to make an angler pause before the pan."
L["variety.8365.red-spotted.name"] = "Red-spotted"
L["variety.8365.steelhead.description"] = "Grey-blue and bright, from big waters. Pulls like it means it."
L["variety.8365.steelhead.name"] = "Steelhead"
